const item = $input.first();
const base64Image = item.json.base64Image;
const mimeType = item.json.mimeType;
const fileName = item.json.fileName;

// Split image into 3x3 grid (9 sections)
const sections = [];

for (let row = 0; row < 3; row++) {
  for (let col = 0; col < 3; col++) {
    sections.push({
      json: {
        base64Image: base64Image,
        mimeType: mimeType,
        fileName: fileName,
        section: `row_${row + 1}_col_${col + 1}`,
        focusArea: `${getRowName(row)}_${getColName(col)}`,
        rowIndex: row,
        colIndex: col
      }
    });
  }
}

// Helper functions to get descriptive names
function getRowName(row) {
  if (row === 0) return 'top';
  if (row === 1) return 'middle';
  return 'bottom';
}

function getColName(col) {
  if (col === 0) return 'left';
  if (col === 1) return 'center';
  return 'right';
}

return sections;

