// Enhanced function to find bbox coordinates
function findBboxForText(searchText, blocks) {
  if (!searchText || !blocks || blocks.length === 0) return null;

  const normalizedSearch = searchText.toLowerCase().trim().replace(/\s+/g, ' ');
  const searchWords = normalizedSearch.split(/\s+/).filter(w => w.length > 2);

  // Try exact and partial matches first
  for (const block of blocks) {
    if (!block.text || !block.bbox) continue;

    const blockText = block.text.toLowerCase().trim();

    if (blockText === normalizedSearch || 
        blockText.includes(normalizedSearch) || 
        normalizedSearch.includes(blockText)) {
      console.log(`Match found: "${searchText}" -> "${block.text}"`);
      return block.bbox;
    }
  }

  // Try word-based matching
  let bestMatch = null;
  let bestScore = 0;

  for (const block of blocks) {
    if (!block.text || !block.bbox) continue;
    const blockText = block.text.toLowerCase();

    let score = 0;
    for (const word of searchWords) {
      if (blockText.includes(word)) score++;
    }

    if (score > bestScore && score >= Math.min(2, searchWords.length)) {
      bestScore = score;
      bestMatch = block.bbox;
    }
  }

  if (bestMatch) {
    console.log(`Fuzzy match found for: "${searchText}"`);
  }

  return bestMatch;
}

